<script setup lang="ts">
import{onMounted,reactive,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{api,type ApiResponse,type Product,type Sku}from'@whaashop/shared';
interface Page<T>{items:T[];total:number}interface Rec{id?:number;productId?:number;productName?:string;productImage?:string;positionCode:string;sortOrder:number;enabled:boolean}interface Flash{id?:number;productId?:number;productName?:string;productImage?:string;skuId?:number;skuSpec?:string;originalPrice?:number;price?:number;stock:number;perUserLimit:number;startAt:string;endAt:string;enabled:boolean}
const recs=ref<Rec[]>([]),sales=ref<Flash[]>([]),products=ref<Product[]>([]),skus=ref<Sku[]>([]),recDialog=ref(false),saleDialog=ref(false),recPage=ref(1),salePage=ref(1),recTotal=ref(0),saleTotal=ref(0),size=10,rec=reactive<Rec>({positionCode:'HOME_FEATURED',sortOrder:0,enabled:true}),sale=reactive<Flash>({stock:10,perUserLimit:1,startAt:'',endAt:'',enabled:false});
async function load(){const[r,s,p]=await Promise.all([api.get<ApiResponse<Page<Rec>>>('/admin/recommendations',{params:{page:recPage.value,size}}),api.get<ApiResponse<Page<Flash>>>('/admin/flash-sales',{params:{page:salePage.value,size}}),api.get<ApiResponse<Page<Product>>>('/admin/products',{params:{page:1,size:200}})]);recs.value=r.data.data.items;recTotal.value=r.data.data.total;sales.value=s.data.data.items;saleTotal.value=s.data.data.total;products.value=p.data.data.items}
function editRec(v?:Rec){Object.assign(rec,v??{id:undefined,productId:undefined,positionCode:'HOME_FEATURED',sortOrder:0,enabled:true});recDialog.value=true}async function editSale(v?:Flash){Object.assign(sale,v??{id:undefined,productId:undefined,skuId:undefined,price:undefined,stock:10,perUserLimit:1,startAt:'',endAt:'',enabled:false});skus.value=[];if(sale.productId)await loadSkus(sale.productId);saleDialog.value=true}async function loadSkus(productId:number){const{data}=await api.get<ApiResponse<{product:Product;skus:Sku[]}>>(`/shop/products/${productId}`);skus.value=data.data.skus;if(!skus.value.some(v=>v.id===sale.skuId))sale.skuId=undefined}
async function saveRec(){if(!rec.productId)return ElMessage.warning('请选择商品');await api.post('/admin/recommendations',rec);recDialog.value=false;ElMessage.success('推荐位已保存');load()}async function saveSale(){if(!sale.productId||!sale.skuId)return ElMessage.warning('请选择商品和规格');await api.post('/admin/flash-sales',{id:sale.id,skuId:sale.skuId,price:sale.price,stock:sale.stock,perUserLimit:sale.perUserLimit,startAt:sale.startAt,endAt:sale.endAt,enabled:sale.enabled});saleDialog.value=false;ElMessage.success('秒杀活动已保存');load()}async function remove(type:'recommendations'|'flash-sales',id:number){await ElMessageBox.confirm('确认删除？','提示');await api.delete(`/admin/${type}/${id}`);load()}function position(v:string){return v==='HOME_NEW'?'首页新品':'首页精选'}function spec(raw?:string){try{return Object.entries(JSON.parse(raw||'{}')).map(([k,v])=>`${k}：${v}`).join(' · ')||'默认规格'}catch{return raw||'默认规格'}}onMounted(load)
</script>
<template><div class="panel"><div class="toolbar"><h2>推荐商品</h2><el-button type="primary" @click="editRec()">新增推荐</el-button></div><el-table :data="recs"><el-table-column label="关联商品" min-width="230"><template #default="s"><div class="linked-product"><el-image :src="s.row.productImage"/><b>{{s.row.productName||'商品已失效'}}</b></div></template></el-table-column><el-table-column label="推荐位置"><template #default="s">{{position(s.row.positionCode)}}</template></el-table-column><el-table-column prop="sortOrder" label="排序"/><el-table-column label="状态"><template #default="s"><el-tag :type="s.row.enabled?'success':'info'">{{s.row.enabled?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作"><template #default="s"><el-button link type="primary" @click="editRec(s.row)">编辑</el-button><el-button link type="danger" @click="remove('recommendations',s.row.id)">删除</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="recPage" :page-size="size" :total="recTotal" layout="total, prev, pager, next" class="pager" @current-change="load"/></div><div class="panel"><div class="toolbar"><h2>秒杀活动</h2><el-button type="primary" @click="editSale()">新增秒杀</el-button></div><el-table :data="sales"><el-table-column label="关联商品" min-width="220"><template #default="s"><div class="linked-product"><el-image :src="s.row.productImage"/><div><b>{{s.row.productName||'商品已失效'}}</b><small>{{spec(s.row.skuSpec)}}</small></div></div></template></el-table-column><el-table-column label="价格"><template #default="s"><b class="sale-price">¥{{s.row.price}}</b><del>¥{{s.row.originalPrice}}</del></template></el-table-column><el-table-column prop="stock" label="活动库存"/><el-table-column prop="perUserLimit" label="每人限购"/><el-table-column prop="startAt" label="开始时间" width="180"/><el-table-column prop="endAt" label="结束时间" width="180"/><el-table-column label="状态"><template #default="s"><el-tag :type="s.row.enabled?'success':'info'">{{s.row.enabled?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作"><template #default="s"><el-button link type="primary" @click="editSale(s.row)">编辑</el-button><el-button link type="danger" @click="remove('flash-sales',s.row.id)">删除</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="salePage" :page-size="size" :total="saleTotal" layout="total, prev, pager, next" class="pager" @current-change="load"/></div><el-dialog v-model="recDialog" title="推荐位" width="500"><el-form label-width="90"><el-form-item label="关联商品"><el-select v-model="rec.productId" filterable placeholder="按名称选择商品" style="width:100%"><el-option v-for="p in products" :key="p.id" :label="p.name" :value="p.id"/></el-select></el-form-item><el-form-item label="推荐位置"><el-select v-model="rec.positionCode"><el-option label="首页精选" value="HOME_FEATURED"/><el-option label="首页新品" value="HOME_NEW"/></el-select></el-form-item><el-form-item label="排序"><el-input-number v-model="rec.sortOrder"/></el-form-item><el-form-item label="启用"><el-switch v-model="rec.enabled"/></el-form-item></el-form><template #footer><el-button @click="recDialog=false">取消</el-button><el-button type="primary" @click="saveRec">保存</el-button></template></el-dialog><el-dialog v-model="saleDialog" title="秒杀活动" width="560"><el-form label-width="100"><el-form-item label="关联商品"><el-select v-model="sale.productId" filterable placeholder="先选择商品" style="width:100%" @change="loadSkus"><el-option v-for="p in products" :key="p.id" :label="p.name" :value="p.id"/></el-select></el-form-item><el-form-item label="商品规格"><el-select v-model="sale.skuId" :disabled="!sale.productId" placeholder="选择SKU规格" style="width:100%"><el-option v-for="s in skus" :key="s.id" :label="`${spec(s.specJson)} / ¥${s.price} / 库存${s.stock}`" :value="s.id"/></el-select></el-form-item><el-form-item label="秒杀价格"><el-input-number v-model="sale.price" :precision="2" :min="0.01"/></el-form-item><el-form-item label="活动库存"><el-input-number v-model="sale.stock" :min="1"/></el-form-item><el-form-item label="每人限购"><el-input-number v-model="sale.perUserLimit" :min="1"/></el-form-item><el-form-item label="开始时间"><el-date-picker v-model="sale.startAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item><el-form-item label="结束时间"><el-date-picker v-model="sale.endAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item><el-form-item label="启用"><el-switch v-model="sale.enabled"/></el-form-item></el-form><template #footer><el-button @click="saleDialog=false">取消</el-button><el-button type="primary" @click="saveSale">保存</el-button></template></el-dialog></template>
<style scoped>.linked-product{display:flex;align-items:center;gap:10px}.linked-product :deep(.el-image){width:46px;height:46px;flex:none;border-radius:7px}.linked-product small{display:block;color:#829ab0}.sale-price{color:#e64919}.sale-price+del{margin-left:6px;color:#9aa9bc}.pager{margin-top:18px;justify-content:flex-end}</style>
